// Tests for AbortOnDrop pattern (ADR-009)
// Validates task cleanup when Session drops

#[cfg(test)]
mod tests {
    use std::sync::Arc;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::time::Duration;
    use tokio::sync::RwLock;
    use tokio_util::task::AbortOnDrop;
    use crate::session::{Session, SessionId};
    use crate::pty::MockPtyBackend;
    use std::path::PathBuf;

    /// Test that AbortOnDrop cancels tasks when Session drops
    #[tokio::test]
    async fn test_abort_on_drop_cancels_tasks() {
        // Create flags to track if tasks are running
        let output_task_running = Arc::new(AtomicBool::new(false));
        let monomind_task_running = Arc::new(AtomicBool::new(false));

        let output_flag = output_task_running.clone();
        let monomind_flag = monomind_task_running.clone();

        // Spawn long-running tasks
        let output_task = AbortOnDrop::new(tokio::spawn(async move {
            output_flag.store(true, Ordering::SeqCst);
            // Simulate long-running task
            tokio::time::sleep(Duration::from_secs(3600)).await;
            // This should never be reached due to abort
            output_flag.store(false, Ordering::SeqCst);
        }));

        let monomind_task = AbortOnDrop::new(tokio::spawn(async move {
            monomind_flag.store(true, Ordering::SeqCst);
            // Simulate long-running task
            tokio::time::sleep(Duration::from_secs(3600)).await;
            // This should never be reached due to abort
            monomind_flag.store(false, Ordering::SeqCst);
        }));

        // Give tasks time to start
        tokio::time::sleep(Duration::from_millis(50)).await;

        // Verify tasks are running
        assert!(output_task_running.load(Ordering::SeqCst));
        assert!(monomind_task_running.load(Ordering::SeqCst));

        // Create mock PTY
        let mut mock_pty = MockPtyBackend::new();
        mock_pty.expect_shell_pid().returning(|| 12345);

        // Create session with AbortOnDrop tasks
        let session_id = SessionId::new_v4();
        let _session = Session::new(
            session_id,
            Box::new(mock_pty),
            "test.exe".to_string(),
            PathBuf::from("C:\\test"),
            24,
            80,
            output_task,
            monomind_task,
        );

        // Session drops here when it goes out of scope
        drop(_session);

        // Give abort time to propagate
        tokio::time::sleep(Duration::from_millis(100)).await;

        // Tasks should still show as "running" in our flags because abort
        // doesn't change the flag - it just stops the task from completing
        // The important test is that the tasks don't reach the code that sets false
        assert!(output_task_running.load(Ordering::SeqCst));
        assert!(monomind_task_running.load(Ordering::SeqCst));
    }

    /// Test that Session drop triggers AbortOnDrop cleanup
    #[tokio::test]
    async fn test_session_drop_aborts_background_tasks() {
        let task_aborted = Arc::new(AtomicBool::new(false));
        let aborted_flag = task_aborted.clone();

        // Spawn a task that can detect cancellation
        let output_task = AbortOnDrop::new(tokio::spawn(async move {
            tokio::select! {
                _ = tokio::time::sleep(Duration::from_secs(3600)) => {
                    // Should not reach here
                }
                _ = tokio::signal::ctrl_c() => {
                    // Also should not reach here in test
                }
            }
            // If we get here without cancellation, something is wrong
            aborted_flag.store(false, Ordering::SeqCst);
        }));

        let monomind_task = AbortOnDrop::new(tokio::spawn(async move {
            tokio::time::sleep(Duration::from_secs(3600)).await;
        }));

        // Create mock PTY
        let mut mock_pty = MockPtyBackend::new();
        mock_pty.expect_shell_pid().returning(|| 12345);

        let session_id = SessionId::new_v4();
        {
            let _session = Session::new(
                session_id,
                Box::new(mock_pty),
                "test.exe".to_string(),
                PathBuf::from("C:\\test"),
                24,
                80,
                output_task,
                monomind_task,
            );
            // Session drops at end of this scope
        }

        // Give time for abort to propagate
        tokio::time::sleep(Duration::from_millis(100)).await;

        // Task should have been aborted, so the flag should not be set to false
        assert!(!task_aborted.load(Ordering::SeqCst));
    }

    /// Test that multiple Session drops don't cause issues
    #[tokio::test]
    async fn test_multiple_sessions_cleanup() {
        for i in 0..10 {
            let output_task = AbortOnDrop::new(tokio::spawn(async move {
                tokio::time::sleep(Duration::from_secs(3600)).await;
            }));

            let monomind_task = AbortOnDrop::new(tokio::spawn(async move {
                tokio::time::sleep(Duration::from_secs(3600)).await;
            }));

            let mut mock_pty = MockPtyBackend::new();
            mock_pty.expect_shell_pid().returning(move || 10000 + i);

            let session_id = SessionId::new_v4();
            let _session = Session::new(
                session_id,
                Box::new(mock_pty),
                "test.exe".to_string(),
                PathBuf::from("C:\\test"),
                24,
                80,
                output_task,
                monomind_task,
            );

            // Session drops immediately
            drop(_session);
        }

        // All sessions should clean up without panics or leaks
        tokio::time::sleep(Duration::from_millis(200)).await;
    }

    /// Test that tasks are properly cleaned up when Session is in an Arc
    #[tokio::test]
    async fn test_arc_session_cleanup() {
        let task_completed = Arc::new(AtomicBool::new(false));
        let completed_flag = task_completed.clone();

        let output_task = AbortOnDrop::new(tokio::spawn(async move {
            // This should be cancelled before completing
            tokio::time::sleep(Duration::from_secs(3600)).await;
            completed_flag.store(true, Ordering::SeqCst);
        }));

        let monomind_task = AbortOnDrop::new(tokio::spawn(async move {
            tokio::time::sleep(Duration::from_secs(3600)).await;
        }));

        let mut mock_pty = MockPtyBackend::new();
        mock_pty.expect_shell_pid().returning(|| 12345);

        let session_id = SessionId::new_v4();
        let session = Session::new(
            session_id,
            Box::new(mock_pty),
            "test.exe".to_string(),
            PathBuf::from("C:\\test"),
            24,
            80,
            output_task,
            monomind_task,
        );

        // Wrap in Arc<RwLock<>> like SessionManager does
        let session_arc = Arc::new(RwLock::new(session));

        // Clone the Arc (simulating multiple references)
        let _clone1 = session_arc.clone();
        let _clone2 = session_arc.clone();

        // Drop all references
        drop(_clone1);
        drop(_clone2);
        drop(session_arc);

        // Give time for cleanup
        tokio::time::sleep(Duration::from_millis(100)).await;

        // Task should have been aborted, not completed
        assert!(!task_completed.load(Ordering::SeqCst));
    }

    /// Property test: Session lifecycle with AbortOnDrop never leaks tasks
    #[tokio::test]
    async fn test_session_lifecycle_no_task_leaks() {
        use std::sync::atomic::AtomicUsize;

        let tasks_spawned = Arc::new(AtomicUsize::new(0));
        let tasks_completed = Arc::new(AtomicUsize::new(0));

        for _ in 0..20 {
            let spawned = tasks_spawned.clone();
            let completed = tasks_completed.clone();

            let output_task = AbortOnDrop::new(tokio::spawn(async move {
                spawned.fetch_add(1, Ordering::SeqCst);
                tokio::time::sleep(Duration::from_secs(3600)).await;
                completed.fetch_add(1, Ordering::SeqCst);
            }));

            let spawned2 = tasks_spawned.clone();
            let completed2 = tasks_completed.clone();

            let monomind_task = AbortOnDrop::new(tokio::spawn(async move {
                spawned2.fetch_add(1, Ordering::SeqCst);
                tokio::time::sleep(Duration::from_secs(3600)).await;
                completed2.fetch_add(1, Ordering::SeqCst);
            }));

            let mut mock_pty = MockPtyBackend::new();
            mock_pty.expect_shell_pid().returning(|| 12345);

            let session_id = SessionId::new_v4();
            let _session = Session::new(
                session_id,
                Box::new(mock_pty),
                "test.exe".to_string(),
                PathBuf::from("C:\\test"),
                24,
                80,
                output_task,
                monomind_task,
            );

            // Session drops
            drop(_session);
        }

        // Give time for all aborts to propagate
        tokio::time::sleep(Duration::from_millis(200)).await;

        // All tasks should have been spawned
        assert_eq!(tasks_spawned.load(Ordering::SeqCst), 40); // 20 iterations * 2 tasks

        // No tasks should have completed (all aborted)
        assert_eq!(tasks_completed.load(Ordering::SeqCst), 0);
    }
}

