// Manual mock PTY backend for testing
// mockall::automock doesn't work well with async_trait, so we implement manually

use async_trait::async_trait;
use crate::pty::{PtyBackend, PtyConfig, PtyResult};
use std::io;

/// Simple mock PTY backend for unit tests
pub struct MockPtyBackend {
    pub shell_pid: u32,
}

impl MockPtyBackend {
    pub fn new(shell_pid: u32) -> Self {
        Self { shell_pid }
    }
}

#[async_trait]
impl PtyBackend for MockPtyBackend {
    async fn create(_config: PtyConfig) -> PtyResult<Self>
    where
        Self: Sized,
    {
        Ok(Self { shell_pid: 12345 })
    }

    async fn read(&mut self, _buf: &mut [u8]) -> io::Result<usize> {
        // Return EOF immediately (simulates terminated PTY)
        Ok(0)
    }

    async fn write(&mut self, _data: &[u8]) -> io::Result<()> {
        Ok(())
    }

    fn resize(&mut self, _rows: u16, _cols: u16) -> PtyResult<()> {
        Ok(())
    }

    fn shell_pid(&self) -> u32 {
        self.shell_pid
    }

    async fn terminate(self: Box<Self>) -> PtyResult<()> {
        Ok(())
    }
}

